    internal bool DesktopUpdateAvailable(){var winget=FindExecutable("winget.exe");if(winget==null)throw new FileNotFoundException("找不到 winget，请使用微软商店更新。");var available=Command(winget,new[]{"upgrade","--source","msstore","--accept-source-agreements","--disable-interactivity"},60000);if(available.TimedOut||available.ExitCode!=0&&unchecked((uint)available.ExitCode)!=0x8a15002b)throw new IOException("桌面版更新清单未能取得，未执行更新；退出码："+available.ExitCode);return Regex.IsMatch(available.Output??"",@"(?<![A-Za-z0-9])9PLM9XGG6VKS(?![A-Za-z0-9])");}
