    internal void ModeState(string mode,string cli){if(!File.Exists(StateFile))return;var state=State();state["ActiveMode"]=mode;state["ActiveCliPath"]=cli;state["LastModeReason"]="已核对保存的 CLI 路径；当前运行实例未核验";NativeData.Write(StateFile,NativeData.Json.Serialize(state));}
    public void SelectCli(string mode){if(DetectCli()==mode){if(mode=="desktop-native")NativeCli(services.Desktop.Discover());else Package(Current);log("CLI 选择与现有设置一致，跳过切换；当前对话不中断。");return;}Stopped();if(mode=="desktop-native"){NativeCli(services.Desktop.Discover());services.Registry.Set("CODEX_CLI_PATH",new RegistryValueState{Exists=false});services.Registry.Set("CODEX_CODE_MODE_HOST_PATH",new RegistryValueState{Exists=false});ModeState("DesktopNativeProtected",null);}else{Package(Current);services.Registry.Set("CODEX_CLI_PATH",new RegistryValueState{Exists=true,Kind="String",Value=Path.Combine(Current,"bin","codex.exe")});services.Registry.Set("CODEX_CODE_MODE_HOST_PATH",new RegistryValueState{Exists=false});ModeState("OfficialCurrent",Path.Combine(Current,"bin","codex.exe"));}ConfigurationEffect.Record(changes,"cli",mode=="desktop-native"?"已移除用户 CLI 路径覆盖，保留机器级设置。":"用户 CLI 路径已指向官方独立组件，保留机器级设置。");}
    internal void CachedCli(string root){if(!NativeData.Inside(root,Path.Combine(Standalone,"releases")))throw new IOException("回滚版本不在官方独立 CLI 缓存中。");Stopped();Package(root);var before=services.Registry.Get("CODEX_CLI_PATH");var host=services.Registry.Get("CODEX_CODE_MODE_HOST_PATH");CaptureSelection();try{var cli=Path.Combine(root,"bin","codex.exe");services.Registry.Set("CODEX_CLI_PATH",new RegistryValueState{Exists=true,Kind="String",Value=cli});services.Registry.Set("CODEX_CODE_MODE_HOST_PATH",new RegistryValueState{Exists=false});ModeState("Rollback",cli);VerifyCli("official-standalone");log("已保存并核对官方独立 CLI 回滚路径（当前实例未核验）："+root);}catch{services.Registry.Set("CODEX_CLI_PATH",before);services.Registry.Set("CODEX_CODE_MODE_HOST_PATH",host);RestoreSelection();throw;}}
    public void VerifyCli(string mode){if(DetectCli()!=mode)throw new IOException("保存的 CLI 路径与本次选择不符，请检查用户或机器级路径覆盖；此检查不代表当前运行实例。");}
    static bool SameTaskUser(string actual,string sid){if(String.Equals(actual,sid,StringComparison.OrdinalIgnoreCase))return true;if(String.IsNullOrWhiteSpace(actual))return false;try{return new NTAccount(actual).Translate(typeof(SecurityIdentifier)).Value==sid;}catch(IdentityNotMappedException){return false;}}
    internal static string GuardMismatch(string xml,string exe,string sid){
        var doc=new System.Xml.XmlDocument{XmlResolver=null};doc.LoadXml(xml);var ns=new System.Xml.XmlNamespaceManager(doc.NameTable);ns.AddNamespace("t","http://schemas.microsoft.com/windows/2004/02/mit/task");Func<string,string> value=path=>{var n=doc.SelectSingleNode("/t:Task/"+path,ns);return n==null?"":n.InnerText;};
        if(doc.SelectNodes("/t:Task/t:Actions/*",ns).Count!=1||!String.Equals(value("t:Actions/t:Exec/t:Command"),exe,StringComparison.OrdinalIgnoreCase)||value("t:Actions/t:Exec/t:Arguments")!="--native-guard")return "任务启动路径或参数与本工具不一致";
        if(!SameTaskUser(value("t:Principals/t:Principal/t:UserId"),sid)||value("t:Principals/t:Principal/t:LogonType")!="InteractiveToken")return "任务运行账户或登录方式不一致";
        var level=value("t:Principals/t:Principal/t:RunLevel");if(level.Length>0&&level!="LeastPrivilege")return "任务并非普通用户运行级别";
        if(doc.SelectNodes("/t:Task/t:Triggers/*",ns).Count!=1||doc.SelectNodes("/t:Task/t:Triggers/t:LogonTrigger",ns).Count!=1||!SameTaskUser(value("t:Triggers/t:LogonTrigger/t:UserId"),sid))return "登录触发器或触发账户不一致";
        foreach(var setting in new[]{"t:Triggers/t:LogonTrigger/t:Enabled","t:Settings/t:Enabled"}){var enabled=value(setting);if(enabled.Length>0&&!System.Xml.XmlConvert.ToBoolean(enabled))return "登录任务或触发器处于禁用状态";}
        return "";
    }
    internal static bool GuardMatches(string xml,string exe,string sid){return GuardMismatch(xml,exe,sid).Length==0;}
    public void Protection(){
        OfficialCli(true);var expected=Path.Combine(GuardRoot,"CodexInitKit.Guard.exe");if(ProtectionInstalled&&File.Exists(expected)&&File.ReadAllBytes(expected).SequenceEqual(File.ReadAllBytes(paths.Self))){try{if(GuardMatches(QueryGuard(),expected,WindowsIdentity.GetCurrent().User.Value)){log("启动保护程序和登录任务一致，跳过替换与注册。");return;}}catch(Exception ex){log("启动保护任务需要重新核对："+ex.Message);}}var state=State();if(!state.ContainsKey("OriginalCliPath"))state["OriginalCliPath"]=services.Registry.Get("CODEX_CLI_PATH").Value;
        Directory.CreateDirectory(GuardRoot);NativeData.NoLinks(GuardRoot);var installed=Path.Combine(GuardRoot,"CodexInitKit.Guard.exe");var stage=installed+".stage-"+Guid.NewGuid().ToString("N");var backup=installed+".previous";
        if(!String.Equals(Path.GetFullPath(paths.Self),Path.GetFullPath(installed),StringComparison.OrdinalIgnoreCase)){try{File.Copy(paths.Self,stage,false);if(File.Exists(installed))File.Replace(stage,installed,backup);else File.Move(stage,installed);ConfigurationEffect.Record(changes,"guard","启动保护程序已保存；登录任务是否注册完成见本阶段结果。");}finally{if(File.Exists(stage))File.Delete(stage);}}
        var taskFile=Path.Combine(GuardRoot,"native-task.xml");NativeData.WriteBytes(taskFile,TaskFileBytes(installed,WindowsIdentity.GetCurrent().User.Value));
        try{RegisterGuard(installed,WindowsIdentity.GetCurrent().User.Value);}catch(UnauthorizedAccessException){if(IsAdministrator())throw new IOException("管理员权限下仍被拒绝注册启动保护任务，请检查现有任务权限。");log("现有启动保护任务受管理员权限保护，需要本次授权；只更新登录任务，不重新执行已完成的初始化步骤。");ElevateGuard(paths.Self);}
        var mismatch=GuardMismatch(QueryGuard(),installed,WindowsIdentity.GetCurrent().User.Value);if(mismatch.Length>0)throw new IOException("登录自动维护任务核验未通过："+mismatch+"。请单独重试启动保护。");
        state["Installed"]=true;state["NativeGuard"]=true;state["InstalledAt"]=DateTime.Now.ToString("s");state["OfficialVersion"]=Package(Current);state["LastUpdateResult"]="原生启动保护安装完成";NativeData.Write(StateFile,NativeData.Json.Serialize(state));ConfigurationEffect.Record(changes,"guard","登录任务已注册并核对触发器、账户与程序路径；本次未实际触发登录维护。");log("启动保护已安装：登录时仅运行内置原生维护，不调用 PowerShell，不强制关闭应用。");
    }
    internal static byte[] TaskFileBytes(string executable,string sid){return Encoding.Unicode.GetPreamble().Concat(Encoding.Unicode.GetBytes(TaskXml(executable,sid))).ToArray();}
    internal static string TaskXml(string executable,string sid){return "<?xml version=\"1.0\" encoding=\"UTF-16\"?><Task version=\"1.2\" xmlns=\"http://schemas.microsoft.com/windows/2004/02/mit/task\"><Triggers><LogonTrigger><Enabled>true</Enabled><UserId>"+sid+"</UserId></LogonTrigger></Triggers><Principals><Principal id=\"Author\"><UserId>"+sid+"</UserId><LogonType>InteractiveToken</LogonType><RunLevel>LeastPrivilege</RunLevel></Principal></Principals><Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><Hidden>true</Hidden><ExecutionTimeLimit>PT5M</ExecutionTimeLimit></Settings><Actions Context=\"Author\"><Exec><Command>"+System.Security.SecurityElement.Escape(executable)+"</Command><Arguments>--native-guard</Arguments></Exec></Actions></Task>";}
    internal void AutoMaintain(){var app=services.Desktop.Discover();if(services.Processes.List(paths,app).Count>0){log("应用正在运行，登录维护已跳过。不会中断任务。");return;}if(!File.Exists(StateFile)||!Convert.ToBoolean(State().ContainsKey("NativeGuard")?State()["NativeGuard"]:false))return;try{NativeCli(app);log("桌面原生组件完整，保留当前用户选择。");}catch{Package(Current);if(DetectCli()=="desktop-native")SelectCli("official-standalone");}}
    public void Browser(){var browser=new NativeDesktopBrowser(paths,services,port,Core.Value(settings,"proxyHost",Core.DefaultProxyHost),log);try{browser.Repair();}finally{if(browser.Changed){var effect=ConfigurationEffect.Create("browser","浏览器启动入口已更新。");effect.evidence="文件写入已完成；隔离环境探针结果见步骤日志，当前组件及真实 Chrome 连接未验收。";changes.Add(effect);}}}
    public void WebSocket(){var report=WebSocketStartup.Prepare(WebSocketSettings.FromOptions(settings,port),services.Desktop.Discover().Install,log);if(Convert.ToBoolean(report["changed"]))ConfigurationEffect.Record(changes,"websocket","WebSocket 代理启动设置已保存至本工具；未修改当前桌面进程环境。");log("@@WS_RESULT@@"+Core.Json.Serialize(report));}
}
